using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.VFX;
namespace MassiveArmy.Planetary
{
    [DefaultExecutionOrder(-220)]public sealed class PlanetTerrainFlightTest:MonoBehaviour
    {
        [Serializable]sealed class Report{public string status="PASS",error="";public List<string> checks=new List<string>();public float terrainRange,craterDrop,maximumLockError;public int greenArcPixels;public double impactSubmissionMs;public bool terrainRefreshPending;public uint goalSequenceBefore,goalSequenceAfter;public float goalDelta;}
        Report report=new Report();PlanetDevelopment world;PlanetSpacecraft ship;string output;RenderTexture target,hud,composite;Material compositeMaterial;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-terrain-flight-test")>=0)new GameObject("Terrain and flight integration").AddComponent<PlanetTerrainFlightTest>();}
        void Awake(){var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.deformTerrainOnNuke=true;world.configuredRadius=6000;world.ambientZombies=0;world.requestedCapacity=8192;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Time.captureDeltaTime=1f/60;}
        void Start(){StartCoroutine(Guard());}
        void Check(bool value,string text){if(!value)throw new InvalidOperationException(text);report.checks.Add(text);}
        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);break;}yield return next;}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
        Color32[] Capture(string name,bool withHud=false){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var source=target;if(withHud){Graphics.Blit(target,composite,compositeMaterial);source=composite;}var old=RenderTexture.active;RenderTexture.active=source;var image=new Texture2D(source.width,source.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,source.width,source.height),0,0);image.Apply();var values=image.GetPixels32();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=old;return values;}
        IEnumerator Run(){double deadline=Time.realtimeSinceStartupAsDouble+90;while(world.ShipForValidation==null){if(Time.realtimeSinceStartupAsDouble>deadline)throw new TimeoutException();yield return null;}ship=world.ShipForValidation;world.Paused=true;world.Rig.InputEnabled=false;Check(world.definition.radius==6000&&world.StreamedTerrain!=null&&world.NavigationForValidation.Regional!=null,"Small-world regression fixture retains streaming and regional GPU navigation");
            var surface=new PlanetSurface(world.definition);float low=float.MaxValue,high=float.MinValue;for(int i=0;i<2048;i++){float z=1-2*(i+.5f)/2048,a=i*2.39996323f,r=Mathf.Sqrt(1-z*z);float h=surface.SampleHeight(new Vector3(r*Mathf.Cos(a),z,r*Mathf.Sin(a)));low=Mathf.Min(low,h);high=Mathf.Max(high,h);}report.terrainRange=high-low;Check(report.terrainRange>200,"Planet has substantial geometric hills, valleys and coastline relief");
            target=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGBHalf);target.Create();world.View.enabled=false;world.View.targetTexture=target;
            world.Rig.SetFocusDirection(world.Base.Homes[0]);world.Rig.Distance=10000;world.Rig.RefreshPose();for(int i=0;i<4;i++)yield return null;Capture("planet-relief");
            Vector3 impact=world.Base.Offset(new Vector2(0,700));for(int i=0;surface.SampleHeight(impact)<world.definition.oceanHeight+40&&i<64;i++){float a=i*2.3999632f;impact=world.Base.Offset(new Vector2(Mathf.Cos(a)*700,Mathf.Sin(a)*700));}float before=surface.SampleHeight(impact);world.Rig.SetFocusDirection(impact);world.Rig.Distance=420;world.Rig.RefreshPose();for(int i=0;i<4;i++)yield return null;Capture("before-nuke");int revision=world.StreamedTerrain.Revision;var nav=world.NavigationForValidation;uint oldSequence=nav.GoalSequenceForValidation(0);var oldGoal=nav.GoalForValidation(0);var timer=System.Diagnostics.Stopwatch.StartNew();world.EncounterForValidation.Detonate(impact);timer.Stop();report.impactSubmissionMs=timer.Elapsed.TotalMilliseconds;report.craterDrop=before-surface.SampleHeight(impact);Check(report.craterDrop>19&&report.craterDrop<20,"Real nuke lowers its terrain centre instead of only stamping a decal");Check(world.StreamedTerrain.Revision>revision,"Nuke forces terrain LOD refresh even with a stationary camera");Check(nav.GoalSequenceForValidation(0)==oldSequence,"Terrain edit queues goal rebuild without synchronous goal readback");for(int wait=0;nav.TerrainRefreshPendingForValidation&&wait<120;wait++){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var fence=AsyncGPUReadback.Request(target,0,0,1,0,1,0,1);fence.WaitForCompletion();yield return null;}report.terrainRefreshPending=nav.TerrainRefreshPendingForValidation;report.goalSequenceBefore=oldSequence;report.goalSequenceAfter=nav.GoalSequenceForValidation(0);report.goalDelta=(nav.GoalForValidation(0)-oldGoal).sqrMagnitude;Check(!nav.TerrainRefreshPendingForValidation&&nav.GoalSequenceForValidation(0)>oldSequence&&(nav.GoalForValidation(0)-oldGoal).sqrMagnitude<1e-10f,"Async terrain rebuild completes and preserves the canonical movement goal");nav.InvalidateAsync();nav.RelaxPending(0);var newGoal=world.Base.Offset(new Vector2(0,100));nav.SetGoal(0,newGoal);var commanded=nav.GoalForValidation(0);for(int wait=0;nav.TerrainRefreshPendingForValidation&&wait<120;wait++){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var fence=AsyncGPUReadback.Request(target,0,0,1,0,1,0,1);fence.WaitForCompletion();yield return null;}Check((nav.GoalForValidation(0)-commanded).sqrMagnitude<1e-10f,"A new movement command supersedes a stale async terrain rebuild");foreach(var vfx in FindObjectsByType<VisualEffect>(FindObjectsSortMode.None))vfx.gameObject.SetActive(false);for(int i=0;i<4;i++)yield return null;Capture("after-nuke");
            var player=world.PlayerForValidation;player.CaptureCursor=false;world.AutomaticPlayerStep=false;world.SetFirstPerson(true);player.EnterBodyPosition(surface.GetSurfacePositionPrecise(impact,.05),Vector3.ProjectOnPlane(Vector3.up,impact).normalized);for(int i=0;i<20;i++){ship.Rebase();world.Base.Rebase();Physics.SyncTransforms();player.Step(1f/60,Vector2.zero,Vector2.zero);}Check(Math.Abs(player.PreciseBodyPosition.Magnitude-world.definition.radius-surface.SampleHeight(player.Direction)-.05)<.01,"FPS ground contact agrees with the crater floor");Check(world.View.transform.position.sqrMagnitude==0,"Crater walking retains camera-at-zero precision");world.SetFirstPerson(false);
            double radius=9000,mu=world.definition.gravitationalParameter;var p=new Double3(0,radius,0);var velocity=new Double3(Math.Sqrt(mu/radius),0,0);var rotation=Quaternion.LookRotation(Vector3.down,Vector3.right)*Quaternion.AngleAxis(23,Vector3.forward);ship.SetFlightStateForValidation(new SpacePose{position=p,linearVelocity=velocity,rotation=rotation});world.SetShipControl(true);var initialAxes=Quaternion.LookRotation(Vector3.right,Vector3.up);var offset=Quaternion.Inverse(initialAxes)*rotation;ship.ToggleRotationLock();for(int i=0;i<4500;i++){ship.Integrate(1f/60,Vector3.zero,Vector3.one);var up=ship.Pose.position.Float.normalized;var tangent=Vector3.Cross(Vector3.back,up).normalized;float error=Quaternion.Angle(Quaternion.LookRotation(tangent,up)*offset,ship.Pose.rotation);report.maximumLockError=Mathf.Max(report.maximumLockError,error);}Check(ship.RotationLocked&&report.maximumLockError<.1f,"L preserves the chosen planet-relative attitude and roll through orbital travel despite rotation input");Check(Vector3.Dot(ship.Pose.rotation*Vector3.forward,-ship.Pose.position.Float.normalized)>.9999f,"A planet-facing locked ship continues facing the planet as it orbits");ship.ToggleRotationLock();var oldRotation=ship.Pose.rotation;for(int i=0;i<90;i++)ship.Integrate(1f/60,Vector3.zero,Vector3.up);Check(!ship.RotationLocked&&Quaternion.Angle(oldRotation,ship.Pose.rotation)>20,"Unlock restores manual rotation control");
            var state=ship.Pose;state.rotation=Quaternion.LookRotation(state.linearVelocity.Float.normalized,state.position.Float.normalized);ship.SetFlightStateForValidation(state);ship.ShowTrajectory=false;for(int i=0;i<4;i++)yield return null;var without=Capture("without-trajectory");ship.ShowTrajectory=true;for(int i=0;i<4;i++)yield return null;var with=Capture("trajectory-world");for(int i=0;i<with.Length;i++)if(with[i].g>without[i].g+12&&with[i].g>with[i].r*1.2f&&with[i].g>with[i].b*1.1f)report.greenArcPixels++;Check(ship.TrajectoryPointsForValidation>100&&report.greenArcPixels>50,"Transparent green predicted orbit arc visibly renders in 3D through the cockpit camera");
            hud=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);hud.Create();composite=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);composite.Create();compositeMaterial=new Material(Resources.Load<Shader>("MassiveArmy/PlanetUiComposite"));compositeMaterial.SetTexture("_Ui",hud);ship.SetPilotRenderTarget(hud);for(int i=0;i<4;i++)yield return null;Capture("trajectory-hud",true);Check(world.View.transform.position.sqrMagnitude==0,"Pilot trajectory rendering retains camera-at-zero precision");world.AutomaticPlayerStep=true;
        }
        void OnDestroy(){Time.captureDeltaTime=0;if(world!=null)world.AutomaticPlayerStep=true;foreach(var rt in new[]{target,hud,composite})if(rt!=null){rt.Release();Destroy(rt);}if(compositeMaterial!=null)Destroy(compositeMaterial);}
    }
}

